#!/bin/bash
# Relaunch all evolbench-collab shards with the patient watchdog.
SLBMAN=/home/zhoujie22/river2_0/evol_bench/SkillLearnBench/data/slb-full.jsonl
SFM=/home/zhoujie22/river2_0/.worktrees/cursor-ov-cm-impl/benchmark/evolbench-collab/data/skillflow.jsonl
EVOM=/home/zhoujie22/river2_0/evol_bench/EvoAgentBench/data/evo-code-implementation.jsonl
SLBNOTE="Environment: this task runs in an official Docker container managed by the env server at http://127.0.0.1:8732. First bind it: curl -s -X POST http://127.0.0.1:8732/env -H 'content-type: application/json' -d '{\"task_id\": \"%TASK_ID%\", \"episode_id\": \"%EPISODE_ID%\"}'. Then run every command as: curl -s -X POST http://127.0.0.1:8732/execute -H 'content-type: application/json' -d '{\"episode_id\": \"%EPISODE_ID%\", \"command\": \"<cmd>\", \"timeout_sec\": 600}'. Execute the entire task through this endpoint; do not use your local shell."
SFNOTE="Environment: this task runs in an official Docker container managed by the env server at http://127.0.0.1:8733. First bind it: curl -s -X POST http://127.0.0.1:8733/env -H 'content-type: application/json' -d '{\"task_id\": \"%TASK_ID%\", \"episode_id\": \"%EPISODE_ID%\"}'. Then run every command as: curl -s -X POST http://127.0.0.1:8733/execute -H 'content-type: application/json' -d '{\"episode_id\": \"%EPISODE_ID%\", \"command\": \"<cmd>\", \"timeout_sec\": 600}' and read produced files through the same endpoint. Work in /root inside the container; do not use your local shell."
setsid /tmp/evol-shard.sh slb1 $SLBMAN slb-full-collab-1 warm,cold "slb_anthropic-poster-design,slb_chinese-poem-generator,slb_court-form-filling,slb_dbscan-parameter-tuning,slb_dependency-vulnerability-check,slb_earthquake-plate-calculation,slb_enterprise-information-search" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=1500000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8732" "COFORGE_EVAL_ENV_NOTE=$SLBNOTE" &
setsid /tmp/evol-shard.sh slb2 $SLBMAN slb-full-collab-1 warm,cold "slb_financial-analysis,slb_fix-security-bug,slb_nlp-paper-reproduction,slb_offer-letter-generator,slb_organize-messy-files,slb_python-scala-translation" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=1500000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8732" "COFORGE_EVAL_ENV_NOTE=$SLBNOTE" &
setsid /tmp/evol-shard.sh slb3 $SLBMAN slb-full-collab-1 warm,cold "slb_schedule-planning,slb_stock-data-visualization,slb_temperature-simulation,slb_travel-planning,slb_video-object-counting,slb_weighted-gdp-calculation" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=1500000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8732" "COFORGE_EVAL_ENV_NOTE=$SLBNOTE" &
setsid /tmp/evol-shard.sh sf1 $SFM sf-full-collab-1 warm,cold "sf_Compensation-Scenario-Modeling,sf_Cross-Format-Data-Reconciliation,sf_DMAIC-Quality-Analysis,sf_Distribution-Center-Auditing,sf_Document-Fraud-Detection" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=2100000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8733" "COFORGE_EVAL_ENV_NOTE=$SFNOTE" &
setsid /tmp/evol-shard.sh sf2 $SFM sf-full-collab-1 warm,cold "sf_Embedded-Data-Repair,sf_Financial-Statement-Rolling,sf_HWPX-Document-Automation,sf_Healthcare-Cost-Benefit-Analysis,sf_Industry-Correlation-Analysis" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=2100000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8733" "COFORGE_EVAL_ENV_NOTE=$SFNOTE" &
setsid /tmp/evol-shard.sh sf3 $SFM sf-full-collab-1 warm,cold "sf_Inventory-&-Finance-Integration,sf_Medical-Data-Standardization,sf_OCR-Data-Extraction,sf_Operational-Recovery-Planning,sf_PPT-Formatting-Optimization" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=2100000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8733" "COFORGE_EVAL_ENV_NOTE=$SFNOTE" &
setsid /tmp/evol-shard.sh sf4 $SFM sf-full-collab-1 warm,cold "sf_Production-Capacity-Planning,sf_SEC-13F-Financial-Analysis,sf_Sales-Pivot-Analysis,sf_Supply-Chain-Replenishment,sf_Weighted-Risk-Assessment" - "COFORGE_EVAL_EPISODE_TIMEOUT_MS=2100000" "COFORGE_EVAL_VERIFY_SIDECAR=http://127.0.0.1:8733" "COFORGE_EVAL_ENV_NOTE=$SFNOTE" &
setsid /tmp/evol-shard.sh evocold1 $EVOM evo-code-full-collab-1 cold - 2:0 &
setsid /tmp/evol-shard.sh evocold2 $EVOM evo-code-full-collab-1 cold - 2:1 &
sleep 2
# evo warm main with the same patient watchdog pattern (fresh log suffix to avoid old summary match)
echo "shards relaunched"
